def _find_older_python():
    "Return python3.11 or python3.12 executable path if available, else None."
    for candidate in ("python3.11", "python3.12", "python3.11.exe", "python3.12.exe"):
        exe = shutil.which(candidate)
        if exe:
            return exe
    return None


def _pipx_fetch_python_args() -> list[str]:
    "pipx flag to download a standalone Python if it's missing, or [] if this pipx can't."
    try:
        out = subprocess.run(
            ["pipx", "install", "--help"], capture_output=True, text=True, timeout=30
        ).stdout or ""
    except Exception:
        return []
    if _re.search(r"--fetch-python[\s={]", out):
        return ["--fetch-python=missing"]  # newer pipx
    if "--fetch-missing-python" in out:
        return ["--fetch-missing-python"]  # older pipx (1.5+)
    return []


