def _git_missing() -> bool:
    "Installing from GitHub needs git on PATH (pip, pipx and uv all call it)."
    if shutil.which("git"):
        return False
    print("ERROR: git was not found. OF-Scraper-Community is installed from GitHub,")
    print("       which needs git. Install it from https://git-scm.com/downloads")
    print("       (Linux: your package manager, e.g. sudo apt install git),")
    print("       then open a new terminal and run this script again.")
    return True


def _run_version_command(cmd: list[str]) -> str | None:
    """Run a version command and return the most likely package x.y.z version found."""
    try:
        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            timeout=10,
        )
    except Exception:
        return None

    candidates: list[str] = []
    combined = result.stdout.splitlines() + result.stderr.splitlines()
    for line in combined:
        line = line.strip()
        if not line:
            continue
        matches = _re.findall(r"(\d+\.\d+\.\d+)", line)
        if matches:
            candidates.extend(matches)

    if not candidates:
        return None

    filtered = [v for v in candidates if v != "0.0.0"]
    if filtered:
        candidates = filtered

    preferred = [v for v in candidates if v.startswith("3.")]
    if preferred:
        candidates = preferred

    return candidates[-1]


def _pipx_ofscraper_exe() -> Path | None:
    """Return the pipx ofscraper executable path if present."""
    if platform.system() == "Windows":
        info = _pipx_package_info("ofscraper")
        if info:
            metadata = info.get("metadata") or {}
            main_pkg = metadata.get("main_package") or {}
            apps = main_pkg.get("apps") or []
            app_paths = main_pkg.get("app_paths") or []
            for entry in app_paths:
                path = entry.get("__Path__") if isinstance(entry, dict) else None
                if path:
                    candidate = Path(path)
                    if candidate.is_file():
                        return candidate
            for app in apps:
                candidate = shutil.which(app)
                if candidate:
                    return Path(candidate)
            venv_dir = info.get("venv_dir")
            if venv_dir:
                for candidate in [Path(venv_dir) / "Scripts" / "ofscraper.exe", Path(venv_dir) / "Scripts" / "ofscraper"]:
                    if candidate.is_file():
                        return candidate

    pipx_home = _get_pipx_home()
    if not pipx_home:
        return None

    candidates = []
    if platform.system() == "Windows":
        candidates.extend([
            pipx_home / "venvs" / "ofscraper" / "Scripts" / "ofscraper.exe",
            pipx_home / "venvs" / "ofscraper" / "Scripts" / "ofscraper",
            pipx_home / "pipx" / "venvs" / "ofscraper" / "Scripts" / "ofscraper.exe",
            pipx_home / "pipx" / "venvs" / "ofscraper" / "Scripts" / "ofscraper",
        ])
    else:
        candidates.append(pipx_home / "venvs" / "ofscraper" / "bin" / "ofscraper")

    for candidate in candidates:
        if candidate.is_file():
            return candidate
    return None


def _pipx_list_json() -> dict | None:
    """Return parsed `pipx list --json` output when available."""
    try:
        result = subprocess.run(["pipx", "list", "--json"], capture_output=True, text=True, timeout=15)
        if result.returncode != 0 or not result.stdout.strip():
            return None
        return json.loads(result.stdout)
    except Exception:
        return None


def _pipx_package_info(package_name: str = "ofscraper") -> dict | None:
    data = _pipx_list_json()
    if not data:
        return None
    venvs = data.get("venvs") or {}
    info = venvs.get(package_name)
    if isinstance(info, dict):
        return info
    return None


def _pipx_list_text() -> str | None:
    """Return plain-text `pipx list` output when available."""
    try:
        result = subprocess.run(["pipx", "list"], capture_output=True, text=True, timeout=15)
        if result.returncode != 0:
            return None
        return result.stdout or ""
    except Exception:
        return None


def _pipx_text_mentions_package(package_name: str = "ofscraper") -> bool:
    text = _pipx_list_text()
    if not text:
        return False
    lowered = text.lower()
    return f"package {package_name.lower()} " in lowered or f" {package_name.lower()} " in lowered


def _windows_ofscraper_cli_version() -> str | None:
    if platform.system() != "Windows":
        return None
    exe = shutil.which("ofscraper") or shutil.which("ofscraper.exe")
    if not exe:
        return None
    return _run_version_command([exe, "--version"])


def _uv_ofscraper_exe() -> Path | None:
    """Return the uv tool ofscraper executable path if present."""
    uv_dir = _get_uv_tool_dir()
    if not uv_dir:
        return None

    candidates = []
    if platform.system() == "Windows":
        candidates.extend([
            uv_dir / "ofscraper" / "Scripts" / "ofscraper.exe",
            uv_dir / "ofscraper" / "Scripts" / "ofscraper",
        ])
    else:
        candidates.append(uv_dir / "ofscraper" / "bin" / "ofscraper")

    for candidate in candidates:
        if candidate.is_file():
            return candidate
    return None


def _get_installed_ofscraper_version(method: str | None = None) -> str | None:
    """Return the installed ofscraper version string, preferring package metadata over CLI parsing."""
    methods_to_try: list[str] = []
    if method and method != "unknown":
        methods_to_try.append(method)
    for candidate in ("pipx", "uv", "pip"):
        if candidate not in methods_to_try:
            methods_to_try.append(candidate)

    for candidate in methods_to_try:
        if candidate == "pipx":
            info = _pipx_package_info("ofscraper")
            if info:
                metadata = info.get("metadata") or {}
                main_pkg = metadata.get("main_package") or {}
                version = main_pkg.get("package_version") or info.get("package_version")
                if version:
                    return str(version)
            if _pipx_text_mentions_package("ofscraper"):
                exe = _pipx_ofscraper_exe()
                if exe:
                    version = _run_version_command([str(exe), "--version"])
                    if version:
                        return version
                exe_path = shutil.which("ofscraper") or shutil.which("ofscraper.exe")
                if exe_path:
                    version = _run_version_command([exe_path, "--version"])
                    if version:
                        return version
            if platform.system() == "Windows":
                version = _windows_ofscraper_cli_version()
                if version:
                    return version
            pkg = _find_pipx_ofscraper_pkg()
            if pkg:
                version = _read_dist_info_version(pkg)
                if version:
                    return version
            exe = _pipx_ofscraper_exe()
            if exe:
                version = _run_version_command([str(exe), "--version"])
                if version:
                    return version
        elif candidate == "uv":
            pkg = _find_uv_ofscraper_pkg()
            if pkg:
                version = _read_dist_info_version(pkg)
                if version:
                    return version
            exe = _uv_ofscraper_exe()
            if exe:
                version = _run_version_command([str(exe), "--version"])
                if version:
                    return version
        elif candidate == "pip":
            try:
                import importlib.metadata
                version = importlib.metadata.version("ofscraper")
                if version:
                    return version
            except Exception:
                pass

    exe = shutil.which("ofscraper")
    if exe:
        version = _run_version_command([exe, "--version"])
        if version:
            return version
    return None


def _gui_dep_names() -> list[str]:
    return [pip_name for _, pip_name, _ in _GUI_DEPS]


def _uv_with_args(pip_names: list[str]) -> list[str]:
    args: list[str] = []
    for pkg in pip_names:
        args += ["--with", pkg]
    return args


def _pipx_install_hint_lines() -> list:
    """How to install pipx on this OS (never an apt command on Windows/macOS)."""
    import importlib.util as _ilu
    system = platform.system()
    py = "python" if system == "Windows" else "python3"
    try:
        module_present = _ilu.find_spec("pipx") is not None
    except Exception:
        module_present = False
    if module_present:
        return [
            "pipx is installed for this Python but is not on your PATH. Run:",
            f"    {py} -m pipx ensurepath",
            "then close this terminal, open a new one and run this script again.",
        ]
    if system == "Windows":
        return [
            "Install it with:",
            "    python -m pip install --user pipx",
            "    python -m pipx ensurepath",
            "then close this terminal, open a new one and run this script again.",
            "(Or choose uv instead, which can download a supported Python for you.)",
        ]
    if system == "Darwin":
        return [
            "Install it with:",
            "    brew install pipx",
            "    pipx ensurepath",
            "then open a new terminal and run this script again.",
        ]
    return [
        "Install it with your package manager, e.g.:",
        "    sudo apt install pipx      (Debian / Ubuntu)",
        "    sudo dnf install pipx      (Fedora)",
        "    sudo pacman -S python-pipx (Arch)",
        "then run: pipx ensurepath, open a new terminal and run this script again.",
        "More: https://pipx.pypa.io/stable/installation/",
    ]


def _print_pipx_missing() -> None:
    print("ERROR: Could not find pipx.")
    for line in _pipx_install_hint_lines():
        print("       " + line)


def _install_ofscraper(method: str, *, force: bool = False, keep_gui_deps: bool = False) -> bool:
    """Install OF-Scraper-Community 3.16.1 from GitHub via pip, pipx, or uv. Returns True on success.

    force=True (the --force option) also reinstalls every package instead of
    reusing what is already there, to repair a broken install:
      uv   -> `uv tool install --force --reinstall ... --with <GUI deps>`
      pipx -> `pipx uninstall ofscraper` first, so the venv is created fresh
      pip  -> `--force-reinstall` (already used for every pip install)
    keep_gui_deps=True (--force --skip-deps) reinstalls only ofscraper and its
    own dependencies and keeps the GUI packages that are already installed.
    """
    if _git_missing():
        return False
    pkg = _install_spec()
    # pipx install takes the bare URL; it reads the name from the package
    pipx_pkg = FORK_GIT_URL
    is_py313_plus = not _python_supported()
    py_ver = f"{sys.version_info.major}.{sys.version_info.minor}"
    is_linux = platform.system() == "Linux"
    is_win = platform.system() == "Windows"

    if force and method == "pipx" and keep_gui_deps:
        # Reinstall inside the existing venv so injected GUI packages stay.
        print(f"Force-reinstalling ofscraper {TARGET_OFSCRAPER_VERSION} inside the pipx venv (GUI packages kept)...")
        cmd = ["pipx", "runpip", "ofscraper", "install", "--upgrade", "--force-reinstall", pkg]
        try:
            subprocess.run(cmd, check=True, capture_output=False, cwd=os.path.expanduser("~"))
        except subprocess.CalledProcessError as e:
            print(f"ERROR: Failed to reinstall ofscraper (exit code {e.returncode}).")
            print("If the pipx venv itself is broken, run again with --force but without --skip-deps.")
            return False
        except FileNotFoundError:
            _print_pipx_missing()
            return False
        installed = _get_installed_ofscraper_version(method)
        if not _is_target_version(installed):
            print(f"ERROR: Expected ofscraper {TARGET_OFSCRAPER_VERSION} after install, but found {installed or 'nothing detectable'}.")
            return False
        print(f"ofscraper {installed} reinstalled successfully.")
        return True

    if force and method == "pipx":
        print("Removing the old pipx install of ofscraper so it is rebuilt from scratch...")
        try:
            subprocess.run(["pipx", "uninstall", "ofscraper"], check=False,
                           capture_output=False, cwd=os.path.expanduser("~"))
        except FileNotFoundError:
            _print_pipx_missing()
            return False

    if method == "uv":
        _py_arg = _uv_python_arg()
        if _py_arg:
            print(f"Installing ofscraper {TARGET_OFSCRAPER_VERSION} via uv with Python 3.12 (for Python {py_ver} compatibility)...")
            print("(uv will download Python 3.12 automatically if not already installed)")
        else:
            print(f"Installing ofscraper {TARGET_OFSCRAPER_VERSION} via uv...")
        cmd = ["uv", "tool", "install", "--force", pkg] + _py_arg
        if force:
            # `uv tool install` replaces the whole tool env, so the GUI packages
            # must be listed or they are dropped.
            reinstall = ["--reinstall-package", "ofscraper"] if keep_gui_deps else ["--reinstall"]
            cmd = ["uv", "tool", "install", "--force"] + reinstall + [pkg] + _uv_with_args(_gui_dep_names()) + _py_arg

    elif is_py313_plus and (is_linux or is_win):
        older_py = _find_older_python()
        if method == "pipx":
            if older_py:
                print(f"Installing ofscraper {TARGET_OFSCRAPER_VERSION} via pipx using {older_py}...")
                print(f"(Using {older_py} because Python {py_ver} is outside the supported 3.11 to 3.15)")
                cmd = ["pipx", "install", "--force", pipx_pkg, "--python", older_py]
            elif fetch_args := _pipx_fetch_python_args():
                print(f"Installing ofscraper {TARGET_OFSCRAPER_VERSION} via pipx with Python 3.12...")
                print(f"(Python {py_ver} is outside the supported 3.11 to 3.15;")
                print(" pipx downloads a standalone Python 3.12 if it isn't installed)")
                cmd = ["pipx", "install", "--force", pipx_pkg, "--python", "3.12"] + fetch_args
            else:
                if is_win:
                    print(f"WARNING: Python {py_ver} detected; OF-Scraper-Community 3.16.1 supports Python 3.11 to 3.15.")
                    print("         Recommended:")
                    print("           1) Use uv (option 3) — uv can override pinned versions.")
                    print("           2) Install Python 3.11: https://www.python.org/downloads/release/python-3116/")
                    print("           3) Install MSVC Build Tools: https://visualstudio.microsoft.com/visual-cpp-build-tools/")
                else:
                    print(f"WARNING: Python {py_ver} is not supported (3.11 to 3.15) and no Python 3.11/3.12 was found in PATH.")
                    print("         Recommended fixes:")
                    print("           1) Install Python 3.11:  sudo apt install python3.11")
                    print("              then re-run this script (it will use it automatically).")
                    print("           2) Use uv instead (option 3) — uv can override the pin.")
                print()
                cmd = ["pipx", "install", "--force", pipx_pkg]
        else:
            if older_py:
                print(f"Installing ofscraper {TARGET_OFSCRAPER_VERSION} via pip using {older_py}...")
                print(f"(Using {older_py} because Python {py_ver} is outside the supported 3.11 to 3.15)")
                cmd = [older_py, "-m", "pip", "install", "--upgrade", "--force-reinstall", pkg]
            else:
                if is_win:
                    print(f"WARNING: Python {py_ver} detected; OF-Scraper-Community 3.16.1 supports Python 3.11 to 3.15.")
                    print("         Recommended:")
                    print("           1) Use uv (option 3) — uv can override pinned versions.")
                    print("           2) Install Python 3.11: https://www.python.org/downloads/release/python-3116/")
                    print("           3) Install MSVC Build Tools: https://visualstudio.microsoft.com/visual-cpp-build-tools/")
                else:
                    print(f"WARNING: Python {py_ver} is not supported (3.11 to 3.15) and no Python 3.11/3.12 was found in PATH.")
                    print("         Recommended fixes:")
                    print("           1) Install Python 3.11:  sudo apt install python3.11")
                    print("              then re-run this script (it will use it automatically).")
                    print("           2) Use uv instead (option 3) — uv can override the pin.")
                print()
                cmd = [sys.executable, "-m", "pip", "install", "--upgrade", "--force-reinstall", pkg]

    elif method == "pipx":
        print(f"Installing ofscraper {TARGET_OFSCRAPER_VERSION} via pipx...")
        cmd = ["pipx", "install", "--force", pipx_pkg]
    else:
        print(f"Installing ofscraper {TARGET_OFSCRAPER_VERSION} via pip...")
        cmd = [sys.executable, "-m", "pip", "install", "--upgrade", "--force-reinstall", pkg]

    try:
        subprocess.run(cmd, check=True, capture_output=False)
    except subprocess.CalledProcessError as e:
        print(f"ERROR: Failed to install ofscraper (exit code {e.returncode}).")
        return False
    except FileNotFoundError:
        if method == "uv":
            print("ERROR: Could not find uv. Install it from: https://docs.astral.sh/uv/")
        elif method == "pipx":
            _print_pipx_missing()
        else:
            print("ERROR: Could not find pip. Make sure Python and pip are installed.")
        return False

    installed = _get_installed_ofscraper_version(method)
    if not _is_target_version(installed):
        print(f"ERROR: Expected ofscraper {TARGET_OFSCRAPER_VERSION} after install, but found {installed or 'nothing detectable'}.")
        return False

    print(f"ofscraper {installed} installed successfully.")
    return True


def _prompt_install_method():
    'Interactive menu when ofscraper is not detected. Returns (method, manual_path|None).'
    print()
    print("ofscraper was not detected on this system.")
    print()
    print("Choose an option:")
    print("  1) Install OF-Scraper-Community 3.16.1 with pip")
    print("  2) Install OF-Scraper-Community 3.16.1 with pipx")
    print("  3) Install OF-Scraper-Community 3.16.1 with uv")
    print("  4) Specify install path manually (ofscraper is already installed)")
    print("  5) Exit")
    print()

    method_map = {"1": "pip", "2": "pipx", "3": "uv"}

    while True:
        choice = input("Enter choice (1-5): ").strip()
        if choice in method_map:
            picked = method_map[choice]
            # Catch a missing tool here, before any install warnings, so the
            # user can pick another option instead of the script exiting.
            if picked == "pipx" and shutil.which("pipx") is None:
                print()
                _print_pipx_missing()
                print()
                print("Choose another option, or install pipx and run this script again.")
                continue
            if picked == "uv" and shutil.which("uv") is None:
                print()
                print("ERROR: Could not find uv. Install it from: https://docs.astral.sh/uv/")
                print()
                print("Choose another option, or install uv and run this script again.")
                continue
            return (picked, None)
        if choice == "5":
            return ("exit", None)
        if choice == "4":
            return _prompt_manual_path()
        print("Please enter a number from 1 to 5.")


def _prompt_manual_path():
    'Prompt for a manual ofscraper package path. Returns (method_guess, path_str).'
    print()
    print("Enter the path to your ofscraper package directory")
    print("(the folder containing __main__.py):")

    for attempt in range(3):
        raw = input("> ").strip().strip('"').strip("'")
        if not raw:
            print("No path entered. Please try again.")
            continue

        p = Path(raw).resolve()
        if not p.exists():
            print(f"Path does not exist: {p}")
            if attempt < 2:
                print("Please try again.")
            continue
        if not p.is_dir():
            print(f"Path is not a directory: {p}")
            if attempt < 2:
                print("Please try again.")
            continue
        if not (p / "__main__.py").is_file():
            print(f"Directory does not contain __main__.py: {p}")
            print("Make sure this is the ofscraper package directory.")
            if attempt < 2:
                print("Please try again.")
            continue

        path_lower = str(p).lower()
        if "pipx" in path_lower:
            method = "pipx"
        elif "uv" in path_lower and "tools" in path_lower:
            method = "uv"
        else:
            method = "pip"

        print(f"Path verified: {p}")
        return (method, str(p))

    print("ERROR: Could not validate path after 3 attempts.")
    return ("exit", None)


def _version_tuple(v: str) -> tuple:
    try:
        return tuple(int(x) for x in v.split("."))
    except Exception:
        return (0, 0, 0)


def _check_and_offer_upgrade(method: str) -> bool:
    """Check installed ofscraper version; if missing offer install, if older than target offer upgrade."""
    installed = _get_installed_ofscraper_version(method)

    if installed is None:
        print()
        print(f"ofscraper {TARGET_OFSCRAPER_VERSION} does not appear to be installed.")
        while True:
            answer = input(f"Install ofscraper {TARGET_OFSCRAPER_VERSION} now? (yes/no): ").strip().lower()
            if answer in ("yes", "y"):
                if not _install_ofscraper(method):
                    print("Installation failed.")
                    return False
                return True
            if answer in ("no", "n"):
                while True:
                    ans2 = input("Continue patching without installing? (yes/no): ").strip().lower()
                    if ans2 in ("yes", "y"):
                        return True
                    if ans2 in ("no", "n"):
                        print("Aborted.")
                        return False
                    print("Please enter 'yes' or 'no'.")
            else:
                print("Please enter 'yes' or 'no'.")

    installed_tuple = _base_version(installed)
    target_tuple = _version_tuple(TARGET_OFSCRAPER_VERSION)

    if installed_tuple == target_tuple:
        print(f"Installed ofscraper version: {installed} (OK)")
        return True

    print()
    print(f"Installed ofscraper version: {installed}")
    print(f"This patch is made for OF-Scraper-Community {TARGET_OFSCRAPER_VERSION}.")
    if installed_tuple > target_tuple:
        print("Your version is newer. The patch replaces some of its files with the")
        print(f"{TARGET_OFSCRAPER_VERSION} versions, which can undo newer fixes.")
        print()
        while True:
            answer = input("Patch it anyway? (yes/no): ").strip().lower()
            if answer in ("yes", "y"):
                return True
            if answer in ("no", "n"):
                print("Aborted.")
                return False
            print("Please enter 'yes' or 'no'.")
    if installed_tuple < (3, 16, 0):
        print("Versions before 3.16 are the older upstream OF-Scraper (from PyPI),")
        print("which this patch does not fit. Use patch_ofscraper_3.14.7_gui.py for 3.14.7.")
    print()

    while True:
        answer = input(f"Install OF-Scraper-Community {TARGET_OFSCRAPER_VERSION} from GitHub now? (yes/no): ").strip().lower()
        if answer in ("yes", "y"):
            if not _install_ofscraper(method):
                print("Upgrade failed. Continuing with current version...")
            return True
        if answer in ("no", "n"):
            while True:
                ans2 = input("Continue patching without upgrading? (yes/no): ").strip().lower()
                if ans2 in ("yes", "y"):
                    return True
                if ans2 in ("no", "n"):
                    print("Aborted.")
                    return False
                print("Please enter 'yes' or 'no'.")
        else:
            print("Please enter 'yes' or 'no'.")


def _backup_files(target_pkg: Path, backup_root: Path, rel_paths: list[str]) -> None:
    for rel in rel_paths:
        dst = backup_root / rel
        src = target_pkg / rel
        dst.parent.mkdir(parents=True, exist_ok=True)
        if src.exists():
            shutil.copy2(src, dst)


def _apply_zip(target_pkg: Path, zip_bytes: bytes, *, dry_run: bool = False) -> None:
    zf = zipfile.ZipFile(io.BytesIO(zip_bytes), "r")
    for name in zf.namelist():
        if name.startswith("/") or name.startswith("\\") or ".." in Path(name).parts:
            raise RuntimeError(f"Unsafe path in patch zip: {name!r}")
        out_path = target_pkg / name
        if dry_run:
            continue
        out_path.parent.mkdir(parents=True, exist_ok=True)
        with zf.open(name) as src, open(out_path, "wb") as dst:
            shutil.copyfileobj(src, dst)


def restore(backup_dir: Path, target_pkg: Path | None = None) -> None:
    target_pkg = target_pkg or _pick_site_packages_ofscraper_dir()
    backup_dir = Path(backup_dir).resolve()
    if not backup_dir.is_dir():
        raise SystemExit(f"Backup dir does not exist: {backup_dir}")
    for rel in FILES:
        src = backup_dir / rel
        if not src.exists():
            continue
        dst = target_pkg / rel
        dst.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(src, dst)
    print(f"Restored {len(FILES)} file(s) into {target_pkg}")


def apply(*, target: str | None = None, backup_dir: str | None = None, dry_run: bool = False) -> int:
    try:
        target_pkg = Path(target).resolve() if target else _pick_site_packages_ofscraper_dir()
    except Exception as e:
        print(f"ERROR: could not locate installed ofscraper: {e}")
        return 2

    if not target_pkg.exists():
        print(f"ERROR: target package dir does not exist: {target_pkg}")
        return 2

    ts = _dt.datetime.now().strftime("%Y%m%d_%H%M%S")
    backup_root = Path(backup_dir).resolve() if backup_dir else Path(tempfile.gettempdir()) / f"ofscraper_patch_backup_{PATCH_ID}_{ts}"
    if not dry_run:
        backup_root.mkdir(parents=True, exist_ok=True)

    zip_bytes = base64.b64decode(ZIP_B64.encode("ascii"))

    print(f"Patch ID: {PATCH_ID}")
    print(f"Target:   {target_pkg}")
    print(f"Files:    {FILE_COUNT}")
    print(f"Dry-run:  {dry_run}")
    if not dry_run:
        print(f"Backup:   {backup_root}")

    try:
        _backup_files(target_pkg, backup_root, FILES)
        _apply_zip(target_pkg, zip_bytes, dry_run=dry_run)
    except PermissionError as e:
        print(f"ERROR: permission denied writing to {target_pkg}")
        print("Try running this script in an elevated terminal (Administrator).")
        print(f"Details: {e}")
        return 3
    except Exception as e:
        print(f"ERROR: patch failed: {e}")
        if not dry_run:
            print(f"You can restore from backup: {backup_root}")
        return 1

    if dry_run:
        print("Dry-run complete (no files written).")
    else:
        print("Patch applied successfully.")
        print(f'If you need to undo: run with --restore "{backup_root}"')
    return 0


def main() -> int:
    ap = argparse.ArgumentParser(
        description="Patch pip/pipx/uv-installed OF-Scraper-Community 3.16.1 with GUI-enabled files (Windows & Linux).",
    )
    ap.add_argument("--target", help="Explicit path to installed ofscraper package dir (site-packages/ofscraper).")
    ap.add_argument("--backup-dir", help="Where to store backups (defaults to temp).")
    ap.add_argument("--dry-run", action="store_true", help="Print what would happen; don't write files.")
    ap.add_argument("--skip-deps", "--skip-pyqt6", dest="skip_deps", action="store_true",
                    help="Skip automatic GUI dependency installation (PyQt6, PyQt6-WebEngine, browser_cookie3).")
    ap.add_argument("-y", "--yes", action="store_true", help="Skip the confirmation warning prompt.")
    ap.add_argument("--force", action="store_true",
                    help=f"Reinstall ofscraper {TARGET_OFSCRAPER_VERSION} and all GUI dependencies from scratch, "
                         "then patch. Use it to repair a broken or corrupt install. "
                         "With --skip-deps, only ofscraper is reinstalled.")
    ap.add_argument("--restore", help="Restore from a given backup directory.")
    args = ap.parse_args()

    if args.restore and args.force:
        ap.error("--force can't be used with --restore")

    if args.restore:
        if not _confirm_warning(skip=args.yes):
            print("Aborted.")
            return 0
        restore(Path(args.restore), Path(args.target).resolve() if args.target else None)
        return 0

    if not _confirm_warning(skip=args.yes):
        print("Aborted.")
        return 0

    # Check Python version (OF-Scraper-Community 3.16.1 requires Python >=3.11, <3.16)
    ver = sys.version_info
    print(f"Python version:  {ver.major}.{ver.minor}.{ver.micro}")
    if not _python_supported(ver):
        print()
        print("WARNING: Python {}.{}.{} detected.".format(ver.major, ver.minor, ver.micro))
        print("         OF-Scraper-Community 3.16.1 and this GUI patch need Python 3.11 to 3.15.")
        print("         Recommended Python version: 3.11.x or 3.12.x")
        print()
        while True:
            answer = input("Open browser to download Python 3.11.6? (yes/no): ").strip().lower()
            if answer in ("yes", "y"):
                import webbrowser
                webbrowser.open("https://www.python.org/downloads/release/python-3116/")
                print("Browser opened. Install Python 3.11.6, then re-run this script.")
                return 0
            if answer in ("no", "n"):
                break
            print("Please enter 'yes' or 'no'.")

        while True:
            answer = input("Continue anyway with Python {}.{}.{}? (yes/no): ".format(
                ver.major, ver.minor, ver.micro)).strip().lower()
            if answer in ("yes", "y"):
                break
            if answer in ("no", "n"):
                print("Aborted.")
                return 0
            print("Please enter 'yes' or 'no'.")
        print()

    # Detect platform and install method
    plat = platform.system()
    method = _detect_install_method()
    if plat == "Windows":
        if _pipx_text_mentions_package("ofscraper") or _windows_ofscraper_cli_version() is not None:
            method = "pipx"
    print(f"Platform:        {plat}")
    print(f"Install method:  {method}")
    print()

    just_installed = False
    if method == "unknown":
        choice_method, manual_path = _prompt_install_method()
        if choice_method == "exit":
            print("Aborted.")
            return 0
        if manual_path:
            args.target = manual_path
            method = choice_method
        else:
            if not _install_ofscraper(choice_method):
                return 5
            just_installed = True
            method = choice_method
            method_check = _detect_install_method()
            if method_check != "unknown":
                method = method_check
        print(f"Install method:  {method}")
        print()

    # uv: the forced ofscraper install below already reinstalls the GUI packages.
    gui_deps_done = False
    if args.force and not just_installed:
        what = "ofscraper" if args.skip_deps else "ofscraper and all GUI dependencies"
        if args.dry_run:
            print(f"Dry run: --force would reinstall {what} {TARGET_OFSCRAPER_VERSION} via {method}.")
        else:
            print(f"--force: reinstalling {what} ({TARGET_OFSCRAPER_VERSION}) via {method} from scratch...")
            if not _install_ofscraper(method, force=True, keep_gui_deps=args.skip_deps):
                print("Force reinstall failed.")
                return 5
            gui_deps_done = method == "uv"
        print()
    # Check installed ofscraper version and offer the 3.16.1 install if it differs
    elif not _check_and_offer_upgrade(method):
        return 0

    # Re-detect after a potential install so apply() finds the correct location
    if not args.target:
        method_check = _detect_install_method()
        if method_check == "unknown" and plat == "Windows":
            if _pipx_text_mentions_package("ofscraper") or _windows_ofscraper_cli_version() is not None:
                method_check = "pipx"
        if method_check != "unknown":
            if method_check != method:
                method = method_check
                print(f"Install method (re-detected): {method}")
                print()

    if not args.skip_deps and not gui_deps_done:
        force_deps = args.force and not args.dry_run
        if not _install_gui_deps(method, force=force_deps):
            return 4

    result = apply(target=args.target, backup_dir=args.backup_dir, dry_run=args.dry_run)
    if result == 0 and not args.dry_run and not args.yes:
        print()
        while True:
            answer = input("Launch OF-Scraper GUI now? (yes/no): ").strip().lower()
            if answer in ("yes", "y"):
                print("Starting OF-Scraper GUI...")
                import os as _os
                _exe = shutil.which("ofscraper")
                if not _exe and method == "pipx":
                    _cand = _pipx_ofscraper_exe()
                    if _cand and _cand.exists():
                        _exe = str(_cand)
                if not _exe and method == "uv":
                    _cand = _uv_ofscraper_exe()
                    if _cand and _cand.exists():
                        _exe = str(_cand)
                if _exe:
                    _cmd = [_exe, "--gui"]
                else:
                    _cmd = [sys.executable, "-m", "ofscraper", "--gui"]
                _env = _os.environ.copy()
                if platform.system() == "Linux" and "QT_QPA_PLATFORM" not in _env:
                    _env["QT_QPA_PLATFORM"] = "xcb"
                subprocess.Popen(_cmd, cwd=str(Path.home()), env=_env)
                break
            if answer in ("no", "n"):
                break
            print("Please enter 'yes' or 'no'.")
    return result


if __name__ == "__main__":
    raise SystemExit(main())
